message.content:
Report on the word the evidence gives.

<evidence_schema>
{
  "description": "Where the word comes from.",
  "type": "object",
  "properties": {
    "Word": {
      "description": "The word to report on.",
      "type": "string"
    },
    "Language": {
      "description": "The language the word is in.",
      "type": "string"
    },
    "SeenIn": {
      "description": "Sentences the word was read in, one a string.",
      "type": "array",
      "items": {
        "type": [
          "string",
          "null"
        ]
      }
    }
  },
  "required": [
    "Word",
    "Language",
    "SeenIn"
  ],
  "additionalProperties": false
}
</evidence_schema>

<evidence>
{
  "Word": "pöllö",
  "Language": "Finnish",
  "SeenIn": [
    "Pöllö huhuilee yöllä metsässä."
  ]
}
</evidence>
